// Shader parameters
const float SCALE = 30.0;
const float SPEED = 5.0;
const float SILKINESS = 1.0;
const float CONTRAST = 5.0;
const float DETAIL = 1.0;
const int ITERATIONS = 5;

// Color palette
const vec3 BG_COLOR = vec3(0.078, 0.125, 0.196);
const vec3 MID_COLOR = vec3(0.294, 0.039, 0.078);
const vec3 SHADOW_COLOR = vec3(0.039, 0.043, 0.082);

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
   // Normalize coordinates with aspect ratio correction
   vec2 uv = (fragCoord.xy - 0.5 * iResolution.xy) / length(iResolution.xy);

   // Convert to polar coordinates
   float len = length(uv);
   float angle = atan(uv.y, uv.x);

   // Centered transformation
   vec2 center = (iResolution.xy / length(iResolution.xy)) / 2.0;
   uv = vec2(
      len * cos(angle) + center.x,
      len * sin(angle) + center.y
   ) - center;

   // Scale and animate
   uv *= SCALE;
   float time = iTime * SPEED;
   vec2 uv2 = uv.xy;

   // Recursive geometric transformation
   for(int i = 0; i < ITERATIONS; i ++ ) {
      float mult = DETAIL * float(i + 1) * 0.2;
      uv2 += uv + cos(len * mult);
      uv += mult * vec2(
         cos(5.1123314 + 0.353 * uv2.y + time * 0.131121),
         sin(uv2.x - 0.113 * time)
      );
      uv -= mult * (cos(uv.x + uv.y) - sin(uv.x * 0.711 - uv.y));
   }

   // Color intensity calculation
   float contrast = (0.25 * CONTRAST + 1.2);
   float intensity = clamp(length(uv) * 0.035 * contrast, 0.0, 2.0);

   // Color blending weights
   float w1 = max(0.0, SILKINESS - contrast * abs(1.0 - intensity));
   float w2 = max(0.0, SILKINESS - contrast * abs(intensity));
   float w3 = 1.0 - min(1.0, w1 + w2);

   // Final color composition
   vec3 color = (0.3 / CONTRAST) * BG_COLOR +
   (1.0 - 0.3 / CONTRAST) * (
      BG_COLOR * w1 +
      MID_COLOR * w2 +
      SHADOW_COLOR * w3
   ) +
   0.3 * max(w1 * 5.0 - 4.0, 0.0) +
   0.4 * max(w2 * 5.0 - 4.0, 0.0);

   fragColor = vec4(color, 1.0);
}
